#!/usr/bin/env bash
set -Eeuo pipefail; STAGE=tools; trap 'rc=$?; printf "STOP stage=%s line=%s exit=%s\n" "$STAGE" "${BASH_LINENO[0]}" "$rc" >&2; exit "$rc"' ERR; printf 'STAGE=%s\n' "$STAGE"; command -v umbreld >/dev/null || { printf 'UNVERIFIED umbreld_missing\n'; exit 20; }; printf 'umbreld=%s\n' "$(command -v umbreld)"; STAGE=umbreld_help; printf 'STAGE=%s\n' "$STAGE"; umbreld --help | sed -n '1,80p'; STAGE=umbreld_client_help; printf 'STAGE=%s\n' "$STAGE"; umbreld client --help | sed -n '1,100p'; STAGE=apps_help; printf 'STAGE=%s\n' "$STAGE"; umbreld client apps --help | sed -n '1,120p'; STAGE=identities; printf 'STAGE=%s\n' "$STAGE"; id umbrel || { printf 'UNVERIFIED umbrel_identity_missing\n'; exit 21; }; getent group docker || printf 'docker_group=absent\n'; STAGE=paths; printf 'STAGE=%s\n' "$STAGE"; for p in /home/umbrel/umbrel /home/umbrel/umbrel/app-data /home/umbrel/umbrel/app-data/openclaw /home/umbrel/umbrel/app-data/openclaw/data /run/zeus-host-runner.sock /run/zeus-host-runner /var/lib/zeus-host-runner /etc/zeus-host-runner; do if test -e "$p"; then stat --printf='path=%n type=%F owner=%U:%G mode=%a\n' -- "$p"; fi; done; STAGE=supervisor_metadata; printf 'STAGE=%s\n' "$STAGE"; if command -v systemctl >/dev/null; then systemctl list-unit-files 'umbrel*' --no-legend 2>/dev/null | sed -n '1,80p' || printf 'supervisor_units=none_or_unavailable\n'; else printf 'systemctl=absent\n'; fi; STAGE=socket_metadata; printf 'STAGE=%s\n' "$STAGE"; if test -S /var/run/docker.sock; then stat --printf='docker_socket=%n owner=%U:%G mode=%a\n' /var/run/docker.sock; else printf 'docker_socket=absent\n'; fi; printf 'NO_MUTATION=TRUE\nNO_SECRET_READ=TRUE\nNO_DOCKER_OPERATION=TRUE\n'
